+import { spawn } from "node:child_process";
+import { randomUUID } from "node:crypto";
+import { resolve } from "node:path";
+import { Pool } from "pg";
+import { drizzle } from "drizzle-orm/node-postgres";
+import { migrate } from "drizzle-orm/node-postgres/migrator";
+import { startGoogle } from "./google";
+
+if (!process.env.TEST_DATABASE_URL)
+  throw new Error(
+    "Set TEST_DATABASE_URL to a disposable local Postgres instance (with CREATE DATABASE permission).",
+  );
+const database = `binden_test_${randomUUID().replaceAll("-", "")}`;
+const admin = new Pool({ connectionString: process.env.TEST_DATABASE_URL });
+await admin.query(`CREATE DATABASE "${database}"`);
+const url = new URL(process.env.TEST_DATABASE_URL);
+url.pathname = `/${database}`;
+const pool = new Pool({ connectionString: url.toString() });
+let app: ReturnType<typeof spawn> | undefined;
+let google: Awaited<ReturnType<typeof startGoogle>> | undefined;
+let closing = false;
+async function cleanup() {
+  if (closing) return;
+  closing = true;
+  app?.kill("SIGTERM");
+  google?.closeAllConnections();
+  google?.close();
+  await pool.end();
+  await admin.query(`DROP DATABASE "${database}" WITH (FORCE)`);
+  await admin.end();
+}
+process.on("SIGTERM", () => {
+  void cleanup().then(() => process.exit());
+});
+process.on("SIGINT", () => {
+  void cleanup().then(() => process.exit());
+});
+try {
+  await migrate(drizzle({ client: pool }), { migrationsFolder: "./drizzle" });
+  google = await startGoogle();
+  app = spawn(
+    process.execPath,
+    [
+      "node_modules/next/dist/bin/next",
+      process.env.E2E_DEV ? "dev" : "start",
+      "--port",
+      "3100",
+      ...(process.env.E2E_DEV ? ["--webpack"] : []),
+    ],
+    {
+      stdio: "inherit",
+      env: {
+        ...process.env,
+        DATABASE_URL: url.toString(),
+        BETTER_AUTH_URL: "http://localhost:3100",
+        BETTER_AUTH_SECRET: "browser-test-secret-at-least-thirty-two-characters",
+        GOOGLE_CLIENT_ID: "test-client",
+        GOOGLE_CLIENT_SECRET: "test-secret",
+        GOOGLE_WORKSPACE_DOMAIN: "workspace.example",
+        NODE_OPTIONS: `--import=${resolve("tests/google-network.mjs")}`,
+      },
+    },
+  );
+  app.on("exit", (code) => {
+    void cleanup().then(() => process.exit(code ?? 1));
+  });
+} catch (error) {
+  await cleanup();
+  throw error;
+}
